/* ==========================================================================
   EVENTLY REALISTIC CAMPUS & REAL COMPETITIVE CODING EVENT DATASET
   Includes exact Codeforces, CodeChef, LeetCode, AtCoder, HackerRank, and College Events
   Period: January 2026 to June 2027 (~350+ Events)
   Baseline "Today" Date: September 19, 2026
   ========================================================================== */

const CURRENT_SIMULATED_DATE = '2026-09-19';

/**
 * Calculates dynamic event status based on current date (2026-09-19)
 */
function getEventStatus(evt, todayStr = CURRENT_SIMULATED_DATE) {
  const evtDate = evt.dateStr;
  const deadline = evt.registrationDeadline || `${evtDate}T23:59:00`;
  const isPast = evtDate < todayStr;
  const isToday = evtDate === todayStr;
  const isFuture = evtDate > todayStr;
  const isDeadlinePassed = deadline < `${todayStr}T00:00:00`;

  let statusText = '';
  let statusBadgeClass = '';
  let canRegister = false;

  if (isPast) {
    statusText = 'Event completed';
    statusBadgeClass = 'badge-completed';
    canRegister = false;
  } else if (isToday) {
    if (isDeadlinePassed) {
      statusText = 'Registration deadline over';
      statusBadgeClass = 'badge-deadline-over';
      canRegister = false;
    } else {
      statusText = 'Event in progress / Today';
      statusBadgeClass = 'badge-today-open';
      canRegister = true;
    }
  } else {
    // Future
    if (isDeadlinePassed) {
      statusText = 'Registration deadline over';
      statusBadgeClass = 'badge-deadline-over';
      canRegister = false;
    } else {
      statusText = 'Registration open';
      statusBadgeClass = 'badge-open';
      canRegister = true;
    }
  }

  return {
    isPast,
    isToday,
    isFuture,
    isDeadlinePassed,
    statusText,
    statusBadgeClass,
    canRegister
  };
}

